; ============================================================
; Zanac v1 - MSX1 (C-BIOS, 60Hz)
; ROM: 32KB loaded at 0x4000-0xbfff
;
; Memory map:
;   0x0000-0x3fff  BIOS (C-BIOS, slot 0 page 0)
;   0x4000-0x7fff  ROM page 1 (first 16KB of this file)
;   0x8000-0xbfff  ROM page 2 (second 16KB of this file)
;   0xC000-0xffff  Work RAM (page 3)
;
; MSX I/O ports (not memory-mapped):
;   0x98/0x99  VDP TMS9918 data/control
;   0xa0-0xa2  PSG AY-3-8910 register/write/read
;   0xa8-0xab  PPI 8255 (slot select, keyboard, cassette)
; ============================================================
	ORG	0x4000
rom_header:
	DW	0x4241						; 0x4000  MSX ROM ID: 0x4241 = 'AB' (little-endian)
INIT:
	DW	0x4010						; 0x4002  INIT entry point - called at startup
STATEMENT:
	DW	0x4743						; 0x4004  STATEMENT entry (0=none)
DEVICE:
	DW	0x3538						; 0x4006  DEVICE entry (0=none)
TEXT:
	DW	0x3030						; 0x4008  TEXT pointer (0=none)
	DB	0x39, 0x00, 0x00, 0x00, 0x00, 0x00		; 0x400a

; ============================================================
; INIT - ROM entry point
; Called by MSX BIOS on startup after ROM header check.
; Header at 0x4000: ID='AB', INIT=0x4010
